// ----------------------
// ฟังก์ชัน parse top
// ----------------------
function parseTopRaw(stdout) {
  const lines = stdout.split("\n").map(l => l.trim()).filter(Boolean);

  const result = {
    system: {},
    tasks: {},
    cpu: {},
    memory: {},
    swap: {},
    processes: []
  };

  // ----------------------
  // System line
  // ----------------------
  const sysLine = lines.find(l => l.startsWith("top -"));
  if (sysLine) {
    const match = sysLine.match(
      /top - ([0-9:]+) up (.*?),\s+(\d+) users?,\s+load average:\s*([0-9.,]+),\s*([0-9.,]+),\s*([0-9.,]+)/
    );
    if (match) {
      result.system = {
        time: match[1],
        uptime: match[2],
        users: Number(match[3]),
        loadavg: {
          "1min": match[4],
          "5min": match[5],
          "15min": match[6]
        }
      };
    }
  }

  // ----------------------
  // Tasks line
  // ----------------------
  const tasksLine = lines.find(l => l.startsWith("Tasks:"));
  if (tasksLine) {
    const match = tasksLine.match(
      /Tasks:\s+(\d+) total,\s+(\d+) running,\s+(\d+) sleeping,\s+(\d+) stopped,\s+(\d+) zombie/
    );
    if (match) {
      result.tasks = {
        total: Number(match[1]),
        running: Number(match[2]),
        sleeping: Number(match[3]),
        stopped: Number(match[4]),
        zombie: Number(match[5])
      };
    }
  }

  // ----------------------
  // CPU line
  // ----------------------
  const cpuLine = lines.find(l => l.startsWith("Cpu"));
  if (cpuLine) {
    const parts = cpuLine.match(
      /([\d.]+)%us.*?([\d.]+)%sy.*?([\d.]+)%ni.*?([\d.]+)%id.*?([\d.]+)%wa.*?([\d.]+)%hi.*?([\d.]+)%si.*?([\d.]+)%st/
    );
    if (parts) {
      result.cpu = {
        user: Number(parts[1]),
        system: Number(parts[2]),
        nice: Number(parts[3]),
        idle: Number(parts[4]),
        wait: Number(parts[5]),
        hardware_irq: Number(parts[6]),
        software_irq: Number(parts[7]),
        steal: Number(parts[8])
      };
    }
  }

  // ----------------------
  // Memory line
  // ----------------------
  const memLine = lines.find(l => l.startsWith("Mem:"));
  if (memLine) {
    const parts = memLine.match(
      /Mem:\s+(\d+)k total,\s+(\d+)k used,\s+(\d+)k free,\s+(\d+)k buffers/
    );
    if (parts) {
      result.memory = {
        total_kb: Number(parts[1]),
        used_kb: Number(parts[2]),
        free_kb: Number(parts[3]),
        buffers_kb: Number(parts[4])
      };
    }
  }

  // ----------------------
  // Swap line
  // ----------------------
  const swapLine = lines.find(l => l.startsWith("Swap:"));
  if (swapLine) {
    const parts = swapLine.match(
      /Swap:\s+(\d+)k total,\s+(\d+)k used,\s+(\d+)k free,\s+(\d+)k cached/
    );
    if (parts) {
      result.swap = {
        total_kb: Number(parts[1]),
        used_kb: Number(parts[2]),
        free_kb: Number(parts[3]),
        cached_kb: Number(parts[4])
      };
    }
  }

  // ----------------------
  // Process list
  // ----------------------
  const headerIndex = lines.findIndex(l => l.startsWith("PID "));
  if (headerIndex !== -1) {
    const procLines = lines.slice(headerIndex + 1);

    for (const line of procLines) {
      const cols = line.split(/\s+/);
      if (cols.length < 12) continue;

      result.processes.push({
        pid: cols[0],
        user: cols[1],
        pr: cols[2],
        ni: cols[3],
        virt: cols[4],
        res: cols[5],
        shr: cols[6],
        state: cols[7],
        cpu: cols[8],
        mem: cols[9],
        time: cols[10],
        command: cols.slice(11).join(" ")
      });
    }
  }

  return result;
}


