// ฟังก์ชัน parse df -h
// --------------------------------------------------
function parseDfH(text) {
  const lines = text.split("\n").map(l => l.trim()).filter(Boolean);

  // ตัด header: "Filesystem Size Used Avail Use% Mounted on"
  const dataLines = lines.slice(1);

  const result = [];

  let currentFs = null;

  for (const line of dataLines) {
    const parts = line.split(/\s+/);

    // กรณีบรรทัด FILESYSTEM แต่ไม่มีข้อมูลอื่น (split เป็น 1 ช่อง)
    // เช่น "/dev/mapper/vg_satien-lv_root"
    if (parts.length === 1 && parts[0].startsWith("/")) {
      currentFs = { filesystem: parts[0] };
      continue;
    }

    // ถ้าบรรทัดข้อมูลต่อจาก FS
    if (currentFs && parts.length >= 5) {
      currentFs.size = parts[0];
      currentFs.used = parts[1];
      currentFs.avail = parts[2];
      currentFs.use_percent = parts[3];
      currentFs.mount = parts[4];
      result.push(currentFs);
      currentFs = null;
      continue;
    }

    // บรรทัดปกติในรูปแบบเดียว เช่น
    // tmpfs  32G  68K  32G  1% /dev/shm
    if (parts.length >= 6) {
      result.push({
        filesystem: parts[0],
        size: parts[1],
        used: parts[2],
        avail: parts[3],
        use_percent: parts[4],
        mount: parts[5]
      });
    }
  }

  return result;
}

// แปลง stdout → JSON
const parsed = parseDfH(stdout);

// --------------------------------------------------
// ส่งออก RAW + JSON + timestamp
// --------------------------------------------------
return [
  {
    json: {
      timestamp: ts,
      raw_stdout: stdout,   // ← RAW เก็บตรงนี้
      parsed_df: parsed     // ← JSON structured
    }
  }
];
